#!/usr/bin/env bash
# Install + verify scripts for social→movie. Run on netpoke-control.
set -euo pipefail
EVAL="${SLOWPOKE_TOP:-$HOME/slowpoke}/evaluation"
mkdir -p "$EVAL"
install() {
  local name="$1" b64="$2"
  echo "$b64" | base64 -d > "$EVAL/$name"
  chmod +x "$EVAL/$name"
  echo "Installed $EVAL/$name ($(wc -l < "$EVAL/$name") lines)"
}
install run_social_movie.sh "$(cat <<'B64EOF'

B64EOF
)"
install preflight_social_movie.sh "$(cat <<'B64EOF'

B64EOF
)"
install verify_benchmark_results.sh "$(cat <<'B64EOF'

B64EOF
)"
echo ""
echo "=== Running preflight ==="
export SLOWPOKE_TOP="${SLOWPOKE_TOP:-$HOME/slowpoke}"
bash "$EVAL/preflight_social_movie.sh"
